use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_battery_sample: Drone_Lifecycle_Governor::Battery_Sample
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_battery_sample(container.api_battery_sample);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(battery_sample: Drone_Lifecycle_Governor::Battery_Sample)
{
  put_battery_sample(battery_sample);
}

/// setter for IN DataPort
pub fn put_battery_sample(value: Drone_Lifecycle_Governor::Battery_Sample)
{
  *extern_api::IN_battery_sample.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_battery_evidence_for_governor() -> Drone_Lifecycle_Governor::Battery_Evidence
{
  return extern_api::OUT_battery_evidence_for_governor.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}

/// getter for OUT DataPort
pub fn get_battery_evidence_for_notice() -> Drone_Lifecycle_Governor::Battery_Evidence
{
  return extern_api::OUT_battery_evidence_for_notice.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
